"""Wallet operations views that are not generated by the default router."""

from decimal import Decimal

from django.db.models import (
    Q,
    Sum,
    Case,
    When,
    F,
    DecimalField,
    Value,
)
from django.db.models.functions import Coalesce
from rest_framework import status
from rest_framework.permissions import IsAuthenticated
from rest_framework.views import APIView

from IDBOOKAPI.mixins import StandardResponseMixin
from apps.authentication.constants import UserGroups
from apps.customer.models import Wallet, WalletTransaction
from apps.customer.serializers import RejectPendingRechargeSerializer


def finance_ops_admin_allowed(request) -> bool:
    if getattr(request.user, "is_superuser", False):
        return True
    active_group = None
    token = getattr(request, "auth", None)
    if token is not None:
        try:
            active_group = token.get("active_group")
        except Exception:
            active_group = None
    if not active_group:
        active_group = getattr(request.user, "default_group", None)
    return active_group in (
        UserGroups.BUSINESS_GRP,
        UserGroups.BUS_ADMIN,
        UserGroups.HTLR_ADMIN,
        UserGroups.FRANCH_ADMIN,
    )


def wallet_transactions_scope_q(wallet: Wallet) -> Q:
    """Match WalletTransaction rows to the same wallet scope as a Wallet row."""
    if wallet.company_id:
        return Q(company_id=wallet.company_id)
    if wallet.agent_id:
        return Q(agent_id=wallet.agent_id)
    return Q(
        user_id=wallet.user_id,
        company_id__isnull=True,
        agent_id__isnull=True,
    )


def transaction_matches_wallet(txn: WalletTransaction, wallet: Wallet) -> bool:
    if wallet.company_id:
        return txn.company_id == wallet.company_id
    if wallet.agent_id:
        return txn.agent_id == wallet.agent_id
    return (
        txn.user_id == wallet.user_id
        and txn.company_id is None
        and txn.agent_id is None
    )


def compute_wallet_ledger_balance(wallet: Wallet):
    """
    Sum Credits minus Debits for Completed, successful rows (ledger truth used for reconcile).
    Returns (balance_decimal, included_row_count).
    """
    scope_q = wallet_transactions_scope_q(wallet)
    qs = WalletTransaction.objects.filter(scope_q).filter(
        status="Completed",
        is_transaction_success=True,
    )
    cnt = qs.count()
    agg = qs.aggregate(
        total=Coalesce(
            Sum(
                Case(
                    When(transaction_type="Credit", then=F("amount")),
                    When(transaction_type="Debit", then=-F("amount")),
                    default=Value(Decimal("0")),
                    output_field=DecimalField(max_digits=24, decimal_places=6),
                )
            ),
            Value(Decimal("0")),
        )
    )
    return agg["total"], cnt


class RejectPendingWalletRechargeView(APIView, StandardResponseMixin):
    """
    POST /api/v1/customer/wallet/pending-recharges/<pk>/reject/
    pk = WalletTransaction primary key (same as Bank Transfers admin table id).
    """

    permission_classes = [IsAuthenticated]

    def post(self, request, pk):
        if not finance_ops_admin_allowed(request):
            return self.get_error_response(
                message="You don't have permission to reject wallet recharges",
                status="error",
                errors=[],
                error_code="PERMISSION_DENIED",
                status_code=status.HTTP_403_FORBIDDEN,
            )

        ser = RejectPendingRechargeSerializer(data=request.data)
        if not ser.is_valid():
            return self.get_error_response(
                message="Validation failed",
                status="error",
                errors=ser.errors,
                error_code="VALIDATION_ERROR",
                status_code=status.HTTP_400_BAD_REQUEST,
            )
        reason = ser.validated_data["reason"]

        try:
            txn = WalletTransaction.objects.get(
                pk=pk,
                status="Pending",
                transaction_for="wallet_recharge",
            )
        except WalletTransaction.DoesNotExist:
            return self.get_error_response(
                message="Pending wallet recharge not found",
                status="error",
                errors=[],
                error_code="NOT_FOUND",
                status_code=status.HTTP_404_NOT_FOUND,
            )

        od = dict(txn.other_details or {})
        od["admin_reject"] = {
            "reason": reason,
            "rejected_by_user_id": request.user.id,
        }
        txn.other_details = od
        txn.status = "Failed"
        txn.is_transaction_success = False
        txn.code = "ADMIN_REJECTED"
        txn.save()

        return self.get_response(
            status="success",
            count=1,
            data={
                "id": txn.id,
                "transaction_id": txn.transaction_id,
                "status": txn.status,
            },
            message="Wallet recharge request rejected",
            status_code=status.HTTP_200_OK,
        )
